def happy_numbers(n):
    def is_happy(num):
        seen = set()
        while num != 1 and num not in seen:
            seen.add(num)
            num = sum(int(digit)**2 for digit in str(num))
        return num == 1

    return [num for num in range(1, n + 1) if is_happy(num)]
