class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 0:
            return 0
        if n == 1:
            return 9 % 1337

        max_num = 10**n - 1
        for a in range(max_num, max_num // 10, -1):
            palindrome = a * (10**(n)) + self.make_palindrome(a, n)
            for b in range(max_num, max((max_num * max_num) ** 0.5, 10**(n-1)), -1):
                if palindrome // b >= max_num:
                    break
                if palindrome % b == 0:
                    return palindrome % 1337
        return -1

    def make_palindrome(self, x: int, n: int) -> int:
        original = x
        while x > 0:
            original = original * 10 + x % 10
            x //= 10
        return original
```

