from typing import List

class Solution:
    def findPairs(self, nums: List[int], k: int) -> int:
        if k < 0:
            return 0

        num_counts = {}
        for num in nums:
            num_counts[num] = num_counts.get(num, 0) + 1

        pairs = 0
        for num in num_counts.keys():
            if k == 0:
                if num_counts[num] > 1:
                    pairs += 1
            else:
                if num + k in num_counts:
                    pairs += 1

        return pairs
```

