class Solution:
    def licenseKeyFormatting(self, S: str, K: int) -> str:
        S = S.replace('-', '').upper()
        if len(S) % K == 0:
            return '-'.join([S[i:i+K] for i in range(0, len(S), K)])
        else:
            return S[:len(S)%K] + '-' + '-'.join([S[i:i+K] for i in range(len(S)%K, len(S), K)])
